/**
 * Типизированный интерфейс HostApi для публичного API публикуемого core'а.
 */
export declare interface HostApi<TSlot extends keyof SlotContextMap = keyof SlotContextMap> {
    /**
     * Текущая тема хоста
     */
    getTheme(): Promise<Theme>;
    /**
     * Текущий язык хоста
     */
    getLanguage(): Promise<string>;
    /**
     * Id пользователя
     */
    getUserId(): Promise<string>;
    /**
     * Id организации
     */
    getOrgId(): Promise<string>;
    /**
     * Сборка для ятима
     */
    getIsYateam(): Promise<boolean>;
    /** Текущее состояние Орбиты */
    getIsOrbita(): Promise<boolean>;
    /**
     * Получить текущий контекст, в котором запущен плагин.
     * Тип возвращаемого значения зависит от слота.
     */
    getContext(): Promise<SlotContextMap[TSlot]>;
    /**
     * Изменить размер окна, в котором запущен плагин
     */
    updateContentSize(payload: ContentSizeUpdateRequest): Promise<void>;
    /**
     * Сообщить, что плагин готов к работе
     */
    notifyReady(): Promise<void>;
    /**
     * Сообщить, что плагин закрыт
     */
    close(payload: PluginClosePayloadMap[TSlot]): Promise<void>;
    /**
     * Заблокировать или разблокировать закрытие плагина хостом.
     * Если плагин использует этот метод, то при попытке закрыть плагин в модалке
     * хост выведет диалог, точно ли хочет закрыть плагин.
     * Передайте `true` / `{ preventClose: true }` чтобы запретить закрытие,
     * `false` / `{ preventClose: false }` / `undefined` — чтобы снять блокировку.
     */
    preventClose(payload: boolean | {
        preventClose?: boolean;
    } | undefined): Promise<void>;
    /**
     * Инициализация плагина
     */
    init(options: HostInitOptions): void;
    /**
     * Текущий слот, в котором открыт плагин.
     * Вызов до init() приведёт к ошибке.
     */
    getSlot(): TSlot;
    /**
     * Сервис, в котором открылся плагин.
     * Вызов до init() приведёт к ошибке.
     */
    getService(): string;
    /**
     * Origin родительского окна (хоста).
     * Вызов до init() приведёт к ошибке.
     */
    getOrigin(): string;
    /**
     * Внутренний урл плагина.
     * Вызов до init() приведёт к ошибке.
     */
    getInnerUrl(): string;
    /**
     * Query-параметры плагина.
     * Вызов до init() приведёт к ошибке.
     */
    getQueryParams(): Record<string, string>;
    /**
     * Идентификатор сущности, переданный хостом в параметрах iframe.
     * Доступен сразу после init() без postMessage-запроса.
     */
    getEntityId(): string | null;
    /**
     * Метаданные сущности, переданные хостом в параметрах iframe.
     * Доступны сразу после init() без postMessage-запроса.
     */
    getEntityMeta(): Record<string, string> | undefined;
    /**
     * Уровень контекста, объявленный в манифесте плагина.
     * 'basic' — только entityId, 'full' — полный контекст слота.
     */
    getContextLevel(): ContextLevel;
    /**
     * Выключить автоматическое изменение размера контейнера
     */
    disableAutoResize(): void;
    /**
     * Получить статус аутентификации по доменам плагина
     */
    externalApiAuthGetStatus(payload: ExternalApiAuthGetStatusPayload): Promise<ExternalApiAuthGetStatusResult>;
    /**
     * Отозвать аутентификацию для указанных доменов
     */
    externalApiAuthRevoke(payload: ExternalApiAuthRevokePayload): Promise<ExternalApiAuthRevokeResult>;
    /**
     * Запросить у пользователя данные для аутентификации по доменам
     */
    externalApiAuthRequest(payload: ExternalApiAuthRequestPayload): Promise<ExternalApiAuthRequestResult>;
    /**
     * Проверить статус аутентификации и запросить данные для неаутентифицированных доменов
     */
    externalApiAuthCheckAndRequest(payload: ExternalApiAuthCheckAndRequestPayload): Promise<ExternalApiAuthCheckAndRequestResult>;
    /**
     * Выполнить прокси-запрос к внешнему API
     */
    externalApiCall(payload: ExternalApiCallPayload): Promise<ExternalApiCallResult>;
}

