/**
 * Single runtime source of truth for the typed tracker slots.
 *
 * These are EXACTLY the keys of {@link SlotContextMap} (36 slots). A
 * compile-time assertion in `SlotContextMap.ts` keeps the two in sync.
 *
 * CLI-only slots (`dock`, experimental, no context type) and messenger-only
 * slots (`user.card.info`) are intentionally NOT listed here — they are
 * declared by the CLI, not by the typed slot registry.
 *
 * The order below mirrors the historical CLI slot order so generated artifacts
 * (e.g. the CLI manifest JSON schema) remain stable.
 */
export declare const TRACKER_SLOTS: readonly ["issue.action", "drawer.issue.action", "issue.block", "drawer.issue.block", "issue.tab", "drawer.issue.tab", "issue.comment.action", "issue.editor.action", "queue.action", "queue.tab", "navigation", "trigger.create.action", "trigger.edit.action", "project.action", "drawer.project.action", "project.block", "drawer.project.block", "project.tab", "drawer.project.tab", "project.editor.action", "portfolio.action", "drawer.portfolio.action", "portfolio.block", "drawer.portfolio.block", "portfolio.tab", "drawer.portfolio.tab", "portfolio.editor.action", "goal.action", "drawer.goal.action", "goal.block", "drawer.goal.block", "goal.tab", "drawer.goal.tab", "goal.editor.action", "attachment.viewer.action", "board.tab"];

/**
 * Tracker API access (`api.tracker.call`) is not part of this contract — it lives in
 * `@weavix/tracker-api-plugin`'s `ApiContract`, kept decoupled so `tracker-core` has no
 * dependency on the Tracker API packages. Compose `TrackerContract & ApiContract` at the
 * point of use if a full host implementation needs both.
 */
export declare type TrackerContract<TSlot extends keyof SlotContextMap = keyof SlotContextMap> = BaseContract<SlotContextMap, PluginClosePayloadMap, TSlot>;

export declare type TrackerSlot = (typeof TRACKER_SLOTS)[number];

